```python
import pixeltable as pxt

@pxt.udf
def word_count(text: str) -> int:
    """Count the number of words in text."""
    if not text:
        return 0
    return len(text.split())

# Get the existing 'docs' table
docs = pxt.db.docs

# Add the computed column 'n_words' that applies word_count to 'content'
docs.add_computed_column(n_words=word_count(docs.content))
